/**
 * Weed Firm — game rules and economy.
 * Pure state + transitions so it can be unit-tested in Node.
 */

export const SAVE_VERSION = 5;
export const POD_COUNT = 6;
export const POD_COSTS = [0, 0, 0, 900, 3200, 10000];

// Deliberately brisk: the first unlocks should land inside the first minute.
export const XP_TABLE = [
  0, 60, 160, 330, 580, 900, 1300, 1780, 2340, 2980, 3700, 4500, 5400,
  6400, 7500, 8700, 10000, 11400, 12900, 14500, 16200
];

const STRAIN_ROWS = [
  // id, name, type, thc, unlock, seed, grow, yield, price, bud color, effect
  ['northern', 'Northern Lights', 'INDICA', 17, 1, 14, 20, 9, 11, 0x6ee27a, 'Relaxing'],
  ['blue', 'Blue Dream', 'SATIVA', 19, 1, 26, 28, 13, 17, 0x79b8ff, 'Euphoric'],
  ['afghani', 'Afghani', 'INDICA', 16, 2, 36, 30, 15, 21, 0x9bc46b, 'Body calm'],
  ['ak47', 'AK-47', 'SATIVA', 19, 2, 52, 34, 17, 25, 0xb9d96b, 'Creative'],
  ['blueberry', 'Blueberry', 'INDICA', 17, 3, 68, 36, 18, 30, 0x7f8dff, 'Happy'],
  ['bubblegum', 'Bubblegum', 'INDICA', 17, 3, 88, 38, 20, 34, 0xd98bd9, 'Uplifting'],
  ['og', 'OG Kush', 'HYBRID', 20, 4, 110, 40, 21, 40, 0x9bd96b, 'Heavy'],
  ['cheese', 'Cheese', 'HYBRID', 17, 4, 135, 43, 22, 45, 0xc9c96b, 'Chatty'],
  ['durban', 'Durban Poison', 'SATIVA', 20, 5, 165, 46, 24, 52, 0xb3d96b, 'Energizing'],
  ['dutch', 'Dutch Treat', 'INDICA', 18, 5, 195, 50, 26, 58, 0x8fc46b, 'Sweet calm'],
  ['g13', 'G13', 'HYBRID', 20, 6, 235, 54, 28, 66, 0x9adf8a, 'Couch lock'],
  ['gsc', 'Girl Scout Cookies', 'HYBRID', 22, 6, 280, 58, 30, 74, 0xc9a06b, 'Blissful'],
  ['gorilla', 'Gorilla Glue #4', 'HYBRID', 25, 7, 340, 62, 32, 84, 0x9adf8a, 'Sticky'],
  ['grape', 'Grape Ape', 'INDICA', 20, 7, 390, 66, 34, 92, 0xa07bff, 'Sedating'],
