  }

  placePod(visual, index) {
    const xs = this.mobile ? MOBILE_X : DESKTOP_X;
    const column = index % 3;
    const row = Math.floor(index / 3);
    visual.group.position.set(xs[column], 0, row === 0 ? FRONT_Z : BACK_Z);
  }

  refreshPod(index) {
    const visual = this.podVisuals[index];
    if (!visual) return;
    const plant = this.state.pods[index]?.plant;

    if (visual.plantRoot) {
      visual.group.remove(visual.plantRoot);
      visual.plantRoot.traverse(child => {
        if (child.isMesh && child.material && child.material.userData?.owned) child.material.dispose();
      });
      visual.plantRoot = null;
    }
    visual.leaves = [];
    visual.buds = null;
    visual.fertGlow = null;
    visual.plant = plant;
    visual.strainId = plant?.strainId ?? null;

    if (!plant) return;
    const strain = strainById(plant.strainId);
    const random = seededRandom(hashString(strain.id) + index * 97);
    const root = new THREE.Group();
    root.position.y = 1.52;

    const leafColor = new THREE.Color(0x4f9c43).lerp(new THREE.Color(strain.bud), 0.16);
    const leafMat = new THREE.MeshStandardMaterial({
      color: leafColor.clone(), roughness: 0.68, metalness: 0.02,
      side: THREE.DoubleSide, emissive: 0x0c1a0c, emissiveIntensity: 0.5
    });
    leafMat.userData.owned = true;
    const stemMat = new THREE.MeshStandardMaterial({ color: 0x3f6b34, roughness: 0.85 });
    stemMat.userData.owned = true;
    visual.leafMat = leafMat;
    visual.leafBase = leafColor.clone();
    visual.stemMat = stemMat;

    const stem = new THREE.Mesh(new THREE.CylinderGeometry(0.032, 0.055, 1.1, 6), stemMat);
    stem.position.y = 0.55;
    root.add(stem);

    // Two side branches.
    for (const side of [-1, 1]) {
      const branch = new THREE.Mesh(new THREE.CylinderGeometry(0.018, 0.028, 0.6, 5), stemMat);
      branch.position.set(side * 0.17, 0.78, 0);
      branch.rotation.z = side * 0.55;
      root.add(branch);
    }

    const nodeStages = [0, 0.14, 0.3];
    nodeStages.forEach((minStage, node) => {
      const pivot = new THREE.Group();
      pivot.position.y = 0.18 + node * 0.3;
      pivot.rotation.y = random() * Math.PI * 2;
      root.add(pivot);

      const count = 5;
      for (let i = 0; i < count; i++) {
        const angle = (i / count) * Math.PI * 2 + random() * 0.25;
        const leafPivot = new THREE.Group();
        leafPivot.rotation.y = angle;
        const mesh = new THREE.Mesh(leafGeometry(0.44 + node * 0.06), leafMat);
        mesh.rotation.x = -1.02 - random() * 0.16;
        mesh.rotation.z = (random() - 0.5) * 0.25;
        mesh.position.y = 0.02;
        leafPivot.add(mesh);
        pivot.add(leafPivot);
        visual.leaves.push({ mesh, minStage });
      }
    });

    const budMat = new THREE.MeshStandardMaterial({
      color: strain.bud, roughness: 0.56, metalness: 0.04,
      emissive: new THREE.Color(strain.bud).multiplyScalar(0.12), emissiveIntensity: 0.7
    });
    budMat.userData.owned = true;
    const pistilMat = new THREE.MeshStandardMaterial({
      color: 0xffb469, emissive: 0xff9a3c, emissiveIntensity: 0.4, roughness: 0.6
    });
    pistilMat.userData.owned = true;

    const buds = new THREE.Group();
    const colas = [
      { x: 0, y: 1.12, z: 0, scale: 1.15 },
      { x: -0.26, y: 0.86, z: 0.04, scale: 0.72 },
      { x: 0.26, y: 0.9, z: -0.03, scale: 0.7 }
    ];
    for (const cola of colas) {
      const cluster = new THREE.Group();
      cluster.position.set(cola.x, cola.y, cola.z);
      for (let i = 0; i < 5; i++) {
        const nug = new THREE.Mesh(new THREE.IcosahedronGeometry(0.135, 1), budMat);
        nug.position.set((random() - 0.5) * 0.17, (random() - 0.5) * 0.2, (random() - 0.5) * 0.17);
        nug.scale.setScalar(0.55 + random() * 0.7);
        nug.rotation.set(random() * 3, random() * 3, random() * 3);
        cluster.add(nug);
      }
      for (let i = 0; i < 4; i++) {
        const pistil = new THREE.Mesh(new THREE.ConeGeometry(0.012, 0.08, 4), pistilMat);
        pistil.position.set((random() - 0.5) * 0.2, 0.1 + random() * 0.1, (random() - 0.5) * 0.2);
        pistil.rotation.z = (random() - 0.5) * 1.4;
        pistil.rotation.x = (random() - 0.5) * 1.4;
        cluster.add(pistil);
      }
      cluster.scale.setScalar(cola.scale);
      buds.add(cluster);
    }
    root.add(buds);
    visual.buds = buds;

    const fertGlow = new THREE.Sprite(new THREE.SpriteMaterial({
      map: this.glowMap, color: 0x9dff5e, transparent: true, opacity: 0.4,
      blending: THREE.AdditiveBlending, depthWrite: false
    }));
    fertGlow.scale.set(0.85, 0.85, 1);
    fertGlow.position.y = 1.25;
    fertGlow.visible = false;
    root.add(fertGlow);
    visual.fertGlow = fertGlow;

    visual.plantRoot = root;
    visual.group.add(root);
  }

  /* ------------------------------------------------------------- dust */

  buildDust() {
    const count = 260;
    const positions = new Float32Array(count * 3);
    const random = seededRandom(12345);
    for (let i = 0; i < count; i++) {
      positions[i * 3] = (random() - 0.5) * 26;
      positions[i * 3 + 1] = random() * 8;
      positions[i * 3 + 2] = (random() - 0.5) * 18 - 1;
    }
    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    const material = new THREE.PointsMaterial({
      size: 0.04, map: this.glowMap, color: 0xd7ffe4, transparent: true,
      opacity: 0.42, depthWrite: false, blending: THREE.AdditiveBlending, sizeAttenuation: true
    });
    this.dust = new THREE.Points(geometry, material);
    this.dust.frustumCulled = false;
    this.scene.add(this.dust);
  }

  /* ---------------------------------------------------------- particles */

  burst(index, color = 0x9dff5e) {
    const visual = this.podVisuals[index];
    if (!visual) return;
    const random = seededRandom((Date.now() & 0xffffff) + index * 13);
    const count = 34;
    const positions = new Float32Array(count * 3);
    const velocities = [];
    const origin = visual.group.position;
    for (let i = 0; i < count; i++) {
      positions[i * 3] = origin.x;
      positions[i * 3 + 1] = 2.1 + random() * 0.5;
      positions[i * 3 + 2] = origin.z;
      const angle = random() * Math.PI * 2;
      const speed = 0.6 + random() * 1.5;
      velocities.push(new THREE.Vector3(
        Math.cos(angle) * speed * 0.7,
        0.8 + random() * 1.6,
        Math.sin(angle) * speed * 0.7
      ));
    }
    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    const material = new THREE.PointsMaterial({
      size: 0.11, map: this.glowMap, color, transparent: true, opacity: 1,
      depthWrite: false, blending: THREE.AdditiveBlending, sizeAttenuation: true
    });
    const points = new THREE.Points(geometry, material);
    points.frustumCulled = false;
    this.scene.add(points);
    this.bursts.push({ points, velocities, life: 0, maxLife: 1.25, geometry, material });
  }

  /* ------------------------------------------------------------ events */

  bindEvents() {
    this.onResize = () => this.resize();
    window.addEventListener('resize', this.onResize);
    window.addEventListener('orientationchange', this.onResize);

    let downX = 0;
    let downY = 0;
    let downTime = 0;
    this.canvas.addEventListener('pointerdown', event => {
      downX = event.clientX;
      downY = event.clientY;
      downTime = performance.now();
    });
    this.canvas.addEventListener('pointerup', event => {
      const distance = Math.hypot(event.clientX - downX, event.clientY - downY);
      if (distance > 10 || performance.now() - downTime > 700) return;
      const index = this.pick(event.clientX, event.clientY);
      if (index >= 0) this.onPick(index);
    });
    this.canvas.addEventListener('pointermove', event => {
      if (event.pointerType !== 'mouse') return;
      this.pointer.x = (event.clientX / window.innerWidth) * 2 - 1;
      this.pointer.y = (event.clientY / window.innerHeight) * 2 - 1;
      const index = this.pick(event.clientX, event.clientY);
      if (index !== this.hovered) {
        this.hovered = index;
        this.canvas.style.cursor = index >= 0 ? 'pointer' : 'default';
      }
    });
    this.canvas.addEventListener('pointerleave', () => {
      this.hovered = -1;
      this.canvas.style.cursor = 'default';
      this.pointer.x = 0;
      this.pointer.y = 0;
    });
  }

  pick(clientX, clientY) {
    if (!this.camera || this.failed) return -1;
    const rect = this.canvas.getBoundingClientRect();
    this.pointerNdc.set(
      ((clientX - rect.left) / rect.width) * 2 - 1,
      -((clientY - rect.top) / rect.height) * 2 + 1
    );
    this.raycaster.setFromCamera(this.pointerNdc, this.camera);
    const hits = this.raycaster.intersectObjects(this.podGroups, true);
    if (!hits.length) return -1;
    let object = hits[0].object;
    while (object && object.userData.pod === undefined) object = object.parent;
    return object ? object.userData.pod : -1;
  }

  setSelected(index) {
    this.selected = index;
  }

  /* ------------------------------------------------------------ layout */

  resize() {
    if (this.failed || !this.renderer) return;
    const width = window.innerWidth;
    const height = window.innerHeight;
    this.mobile = width < 860;
    this.renderer.setSize(width, height, false);
    this.camera.aspect = width / height;

    this.basePos = this.mobile
      ? new THREE.Vector3(0, 11.1, 18.4)
      : new THREE.Vector3(0, 9.1, 14.4);
    this.baseTarget = this.mobile
      ? new THREE.Vector3(0, 0.9, -0.5)
      : new THREE.Vector3(2.15, 1.55, -0.7);
    this.camera.position.copy(this.basePos);
    this.camera.lookAt(this.baseTarget);
    this.camera.updateProjectionMatrix();

    this.podVisuals.forEach((visual, index) => this.placePod(visual, index));
    this.width = width;
    this.height = height;
  }

  /* -------------------------------------------------------------- frame */

  update(dt) {
    if (this.failed || !this.scene) return;
    const time = this.clock.elapsedTime;

    // Camera parallax.
    const targetX = this.basePos.x + this.pointer.x * 0.65;
    const targetY = this.basePos.y - this.pointer.y * 0.32;
    this.camera.position.x += (targetX - this.camera.position.x) * Math.min(1, dt * 3);
    this.camera.position.y += (targetY - this.camera.position.y) * Math.min(1, dt * 3);
    this.camera.lookAt(this.baseTarget);

    // Plants.
    this.podVisuals.forEach((visual, index) => {
      const plant = this.state.pods[index]?.plant;
      if (!visual.plantRoot || !plant) return;
      const progress = plant.progress;
      const scale = 0.34 + 0.66 * easeOut(progress);
      visual.plantRoot.scale.setScalar(scale);
      visual.plantRoot.rotation.z = Math.sin(time * 0.7 + index * 1.7) * 0.016;
      visual.plantRoot.rotation.x = Math.cos(time * 0.5 + index) * 0.008;

      for (const leaf of visual.leaves) {
        leaf.mesh.visible = progress >= leaf.minStage;
      }
      if (visual.buds) {
        const budProgress = smoothstep(0.48, 0.92, progress);
        visual.buds.visible = budProgress > 0.02;
        visual.buds.scale.setScalar(0.25 + 0.75 * budProgress);
      }
      if (visual.fertGlow) {
        visual.fertGlow.visible = Boolean(plant.fertilized);
        visual.fertGlow.material.opacity = 0.25 + Math.sin(time * 2.2 + index) * 0.1;
      }
      if (visual.leafMat) {
        const dryness = Math.min(0.85, (1 - plant.health) * 0.9);
        visual.leafMat.color.copy(visual.leafBase).lerp(new THREE.Color(0x9d8b2e), dryness);
      }

      if (visual.ring) {
        const isSelected = this.selected === index;
        const isHovered = this.hovered === index;
        visual.ring.visible = isSelected || isHovered;
        visual.ringMat.opacity = isSelected ? 0.9 : 0.42;
        const pulse = progress >= 1 ? 1 + Math.sin(time * 4) * 0.06 : 1;
        visual.ring.scale.setScalar(pulse);
      }
      if (visual.glow) {
        visual.glow.material.opacity = 0.42 + Math.sin(time * 1.6 + index * 2.1) * 0.08;
      }
      if (visual.cone) {
        visual.cone.material.opacity = 0.038 + Math.sin(time * 1.3 + index) * 0.008;
      }
    });

    // Dust drift.
    if (this.dust) {
      const positions = this.dust.geometry.attributes.position.array;
      for (let i = 0; i < positions.length; i += 3) {
        positions[i + 1] += dt * 0.06;
        positions[i] += Math.sin(time * 0.2 + positions[i + 2]) * dt * 0.01;
        if (positions[i + 1] > 8) positions[i + 1] = 0.1;
      }
      this.dust.geometry.attributes.position.needsUpdate = true;
    }

    // Particle bursts.
    for (let i = this.bursts.length - 1; i >= 0; i--) {
      const burst = this.bursts[i];
      burst.life += dt;
      const positions = burst.geometry.attributes.position.array;
      for (let p = 0; p < burst.velocities.length; p++) {
        const velocity = burst.velocities[p];
        velocity.y -= dt * 2.4;
        positions[p * 3] += velocity.x * dt;
        positions[p * 3 + 1] += velocity.y * dt;
        positions[p * 3 + 2] += velocity.z * dt;
      }
      burst.geometry.attributes.position.needsUpdate = true;
      burst.material.opacity = Math.max(0, 1 - burst.life / burst.maxLife);
      if (burst.life >= burst.maxLife) {
        this.scene.remove(burst.points);
        burst.geometry.dispose();
        burst.material.dispose();
        this.bursts.splice(i, 1);
      }
    }

    if (this.signGlow) {
      this.signGlow.material.opacity = 0.3 + Math.sin(time * 1.2) * 0.035;
    }

    this.renderer.render(this.scene, this.camera);
  }

  markerPosition(index) {
    if (this.failed || !this.camera) return { x: 0, y: 0, visible: false };
    const visual = this.podVisuals[index];
    this.tmp.set(visual.group.position.x, 3.35, visual.group.position.z);
    this.tmp.project(this.camera);
    return {
      x: (this.tmp.x * 0.5 + 0.5) * this.width,
      y: (-this.tmp.y * 0.5 + 0.5) * this.height,
      visible: this.tmp.z < 1
    };
  }
}

import {
  STRAINS, ITEMS, UPGRADES, starterNoop,
  strainById, isStrainUnlocked, upgradeCost, podCost, readyPods, growingPods,
  stageName, gradeFor, plantQuality, estimateYield, pricePerGram, lotValue,
  totalGrams, seedCount, secondsLeft, formatMoney, formatGrams
} from './game.js';
import { icon } from './icons.js';

const esc = value => String(value).replace(/[&<>"']/g, char => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
}[char]));

const gradeClass = grade => 'g-' + grade.replace('+', 'p');

function statusFor(state, pod) {
  if (!pod.unlocked) return { label: 'Locked', cls: 'locked' };
  if (!pod.plant) return { label: 'Empty', cls: 'empty' };
  if (pod.plant.progress >= 1) return { label: 'Ready', cls: 'ready' };
  if (pod.plant.water <= 0.001) return { label: 'Thirsty', cls: 'thirsty' };
  return { label: stageName(pod.plant), cls: 'growing' };
}

export function growOverviewHtml(state) {
  const ready = readyPods(state).length;
  const growing = growingPods(state).length;
  const owned = state.pods.filter(pod => pod.unlocked).length;
  const nextLocked = state.pods.findIndex(pod => !pod.unlocked);

  const cards = state.pods.map((pod, index) => {
    const status = statusFor(state, pod);
    const plant = pod.plant;
    const strain = plant ? strainById(plant.strainId) : null;
    const progress = plant ? Math.round(plant.progress * 100) : 0;
    return `
      <button type="button" class="pod-mini ${status.cls}" data-action="select-pod" data-pod="${index}">
        <span class="pod-mini-top">
          <b>POT ${String(index + 1).padStart(2, '0')}</b>
          <span class="dot ${status.cls}"></span>
        </span>
        <span class="pod-mini-name">${strain ? esc(strain.name) : status.label}</span>
        <span class="pod-mini-meta">${strain
          ? `${status.label} · ${progress}%`
          : status.cls === 'locked' ? formatMoney(podCost(index)) : 'Tap to plant'}</span>
        <span class="mini-bar"><i style="width:${progress}%"></i></span>
      </button>`;
  }).join('');

  return `
    <div class="panel-head">
      <div>
        <p class="eyebrow">GROW ROOM</p>
        <h2>The Garden</h2>
      </div>
      <span class="chip">${growing} growing</span>
    </div>
    <div class="overview-strip">
      <div class="ov-stat"><small>POTS</small><b>${owned}/6</b></div>
      <div class="ov-stat"><small>READY</small><b class="${ready ? 'lime' : ''}">${ready}</b></div>
      <div class="ov-stat"><small>STASH</small><b>${formatGrams(totalGrams(state))}</b></div>
    </div>
    <div class="pod-grid">${cards}</div>
    <button type="button" class="btn-primary wide" data-action="harvest-all" ${ready ? '' : 'disabled'}>
      ${icon('grow')} Harvest ${ready ? ready + ' ready' : 'all'}
    </button>
    ${nextLocked >= 0 ? `
      <button type="button" class="btn-ghost wide" data-action="unlock-pod" data-pod="${nextLocked}">
        ${icon('plus')} Unlock pot ${nextLocked + 1} · ${formatMoney(podCost(nextLocked))}
      </button>` : ''}
    <div class="tip-card">
      ${icon('info')}
      <p><b>Tap any pot in the room.</b> Plant a seed, water it before the meter empties, then harvest when the buds glow.</p>
    </div>`;
}

export function shopHtml(state, filter = 'unlocked') {
  const unlockedCount = STRAINS.filter(strain => isStrainUnlocked(state, strain.id)).length;
  const fertilizer = state.items.fertilizer ?? 0;
  const list = STRAINS.filter(strain => filter === 'all' || isStrainUnlocked(state, strain.id));
  const cards = list.map(strain => {
    const locked = !isStrainUnlocked(state, strain.id);
    const selected = state.selectedStrain === strain.id;
    const seeds = seedCount(state, strain.id);
    const accent = strain.accent;
    return `
      <article class="strain-card ${locked ? 'locked' : ''} ${selected ? 'selected' : ''}" style="--accent:${accent}">
        <div class="nug-wrap">
          <canvas class="nug" width="96" height="96" data-nug="${strain.id}" aria-hidden="true"></canvas>
          ${seeds > 0 ? `<span class="seed-badge" title="Seeds owned">×${seeds}</span>` : ''}
        </div>
        <div class="strain-main">
          <div class="strain-title">
            <b>${esc(strain.name)}</b>
            <span class="type ${strain.type.toLowerCase()}">${strain.type}</span>
          </div>
          <div class="strain-sub">THC ${strain.thc}% · ${esc(strain.effect)} · ${strain.grow}s</div>
          <div class="strain-stats">
            <span>${strain.yield}g yield</span>
            <span>$${strain.price}/g</span>
          </div>
          ${locked ? `<div class="locked-row">${icon('lock')} Unlocks at level ${strain.level}</div>` : `
            <div class="strain-actions">
              <button type="button" class="btn-mini ${selected ? 'on' : ''}" data-action="select-strain" data-strain="${strain.id}">
                ${selected ? icon('check') + ' Selected' : 'Use'}
              </button>
              <button type="button" class="btn-mini ghost" data-action="buy-seed" data-strain="${strain.id}">
                ${icon('plus')} Seed · ${formatMoney(strain.seed)}
              </button>
            </div>`}
        </div>
      </article>`;
  }).join('');

  return `
    <div class="panel-head">
      <div>
        <p class="eyebrow">DISPENSARY</p>
        <h2>Seeds & Supplies</h2>
      </div>
      <span class="chip">${unlockedCount} strains</span>
    </div>
    <div class="supply-card">
      <span class="supply-ico">${icon('flask')}</span>
      <div class="supply-copy">
        <b>${ITEMS.fertilizer.name}</b>
        <small>${ITEMS.fertilizer.desc}</small>
      </div>
      <span class="owned">${fertilizer} owned</span>
      <button type="button" class="btn-mini" data-action="buy-item" data-item="fertilizer">${formatMoney(ITEMS.fertilizer.price)}</button>
    </div>
    <div class="filter-row">
      <button type="button" class="chip-btn ${filter === 'unlocked' ? 'on' : ''}" data-action="filter" data-filter="unlocked">Unlocked</button>
      <button type="button" class="chip-btn ${filter === 'all' ? 'on' : ''}" data-action="filter" data-filter="all">All strains</button>
    </div>
    <div class="strain-list">${cards}</div>`;
}

export function marketHtml(state) {
  const unlocked = STRAINS.filter(strain => isStrainUnlocked(state, strain.id));
  const movers = [...unlocked]
    .sort((a, b) => (state.market[b.id] ?? 1) - (state.market[a.id] ?? 1))
    .slice(0, 3);

  const moverHtml = movers.map(strain => {
    const multiplier = state.market[strain.id] ?? 1;
    const up = multiplier >= 1;
    return `<span class="mover ${up ? 'up' : 'down'}">${esc(strain.name)} <b>${Math.round(multiplier * 100)}%</b> ${up ? '▲' : '▼'}</span>`;
  }).join('');

  const stashValue = state.lots.reduce((sum, lot) => sum + lotValue(state, lot), 0);
  const lots = state.lots.length
    ? state.lots.map(lot => {
      const strain = strainById(lot.strainId);
      const grade = gradeFor(lot.quality);
      const value = lotValue(state, lot);
      const multiplier = state.market[lot.strainId] ?? 1;
      return `
        <article class="lot-card">
          <canvas class="nug small" width="72" height="72" data-nug="${lot.strainId}" aria-hidden="true"></canvas>
          <div class="lot-main">
            <div class="lot-title"><b>${esc(strain.name)}</b><span class="grade ${gradeClass(grade)}">${grade}</span></div>
            <small>${formatGrams(lot.grams)} · ${formatMoney(pricePerGram(state, lot.strainId, lot.quality))}/g</small>
            <span class="market-tag ${multiplier >= 1 ? 'up' : 'down'}">${Math.round(multiplier * 100)}% market</span>
          </div>
          <div class="lot-sell">
            <b>${formatMoney(value)}</b>
            <button type="button" class="btn-mini" data-action="sell-lot" data-lot="${lot.id}">Sell</button>
          </div>
        </article>`;
    }).join('')
    : `<div class="empty-state">${icon('bud')}<b>Nothing to move</b><small>Harvest a ripe plant. The stash shows up here.</small></div>`;

  return `
    <div class="panel-head">
      <div>
        <p class="eyebrow">BLACK MARKET</p>
        <h2>Move the stash</h2>
      </div>
      <span class="chip live">● LIVE</span>
    </div>
    <div class="movers">${moverHtml}</div>
    <div class="inventory-total">
      <div><small>STASH VALUE</small><b>${formatMoney(stashValue)}</b></div>
      <button type="button" class="btn-primary" data-action="sell-all" ${state.lots.length ? '' : 'disabled'}>
        Sell everything
      </button>
    </div>
    <div class="lot-list">${lots}</div>
    <p class="market-note">${icon('info')} Prices tick every few seconds. Sell the spikes, not the dips.</p>`;
}

export function upgradesHtml(state) {
  const cards = Object.entries(UPGRADES).map(([key, def]) => {
    const level = state.upgrades[key] ?? 0;
    const maxed = level >= def.max;
    const cost = upgradeCost(key, level);
    const affordable = state.cash >= cost;
    const pips = Array.from({ length: def.max }, (_, i) =>
      `<i class="${i < level ? 'on' : ''}"></i>`).join('');
    return `
      <article class="upgrade-card">
        <span class="upgrade-ico">${icon(def.icon)}</span>
        <div class="upgrade-main">
          <div class="upgrade-title">
            <b>${def.name}</b>
            <span class="upgrade-level">Lv ${level}/${def.max}</span>
          </div>
          <small>${def.desc}</small>
          <div class="pips">${pips}</div>
          <div class="effect">${def.effect(level)}${level < def.max ? ` <em>→ ${def.effect(level + 1)}</em>` : ''}</div>
        </div>
        <button type="button" class="btn-buy ${affordable ? '' : 'poor'}" data-action="buy-upgrade" data-key="${key}" ${maxed ? 'disabled' : ''}>
          ${maxed ? 'MAX' : formatMoney(cost)}
        </button>
      </article>`;
  }).join('');

  const lockedPods = state.pods.map((pod, index) => pod.unlocked ? '' : `
    <button type="button" class="btn-ghost wide" data-action="unlock-pod" data-pod="${index}">
      ${icon('plus')} Pot ${index + 1} · ${formatMoney(podCost(index))}
    </button>`).join('');

  return `
    <div class="panel-head">
      <div>
        <p class="eyebrow">THE BACK OFFICE</p>
        <h2>Upgrades</h2>
      </div>
      <span class="chip">Lv ${state.level}</span>
    </div>
    <div class="upgrade-list">${cards}</div>
    ${lockedPods ? `<div class="section-label">Expand the room</div>${lockedPods}` : ''}
    <div class="section-label">Lifetime numbers</div>
    <div class="stats-card">
      <div><small>HARVESTS</small><b>${state.stats.harvested}</b></div>
      <div><small>HARVESTED</small><b>${formatGrams(state.stats.grams)}</b></div>
      <div><small>REVENUE</small><b>${formatMoney(state.stats.revenue)}</b></div>
      <div><small>RAIDS</small><b>${state.stats.raids}</b></div>
    </div>
    <button type="button" class="reset-link" data-action="reset">${icon('refresh')} Reset this grow</button>`;
}

export function drawNug(canvas, strain) {
  if (!canvas || !strain) return;
  const ctx = canvas.getContext('2d');
  const size = canvas.width;
  ctx.clearRect(0, 0, size, size);

  const base = strain.bud;
  const r = (base >> 16) & 255;
  const g = (base >> 8) & 255;
  const b = base & 255;
  const shade = amount => {
    const c = v => Math.max(0, Math.min(255, Math.round(v + amount * 255)));
    return `rgb(${c(r)},${c(g)},${c(b)})`;
  };

  let seed = 2166136261;
  for (let i = 0; i < strain.id.length; i++) {
    seed ^= strain.id.charCodeAt(i);
    seed = Math.imul(seed, 16777619);
  }
  const random = () => {
    seed ^= seed << 13;
    seed ^= seed >>> 17;
    seed ^= seed << 5;
    return ((seed >>> 0) % 10000) / 10000;
  };

  const background = ctx.createRadialGradient(size / 2, size / 2, 4, size / 2, size / 2, size / 2);
  background.addColorStop(0, 'rgba(40,70,45,.5)');
  background.addColorStop(1, 'rgba(8,14,10,0)');
  ctx.fillStyle = background;
  ctx.fillRect(0, 0, size, size);

  for (let i = 0; i < 22; i++) {
    const angle = random() * Math.PI * 2;
    const distance = random() * size * 0.2;
    const x = size / 2 + Math.cos(angle) * distance;
    const y = size / 2 + Math.sin(angle) * distance * 0.9;
    const radius = size * (0.12 + random() * 0.09);
    const gradient = ctx.createRadialGradient(x - radius * 0.35, y - radius * 0.35, radius * 0.15, x, y, radius);
    gradient.addColorStop(0, shade(0.24));
    gradient.addColorStop(0.65, shade(0.02));
    gradient.addColorStop(1, shade(-0.22));
    ctx.fillStyle = gradient;
    ctx.beginPath();
    ctx.ellipse(x, y, radius * (0.8 + random() * 0.4), radius, random() * Math.PI, 0, Math.PI * 2);
    ctx.fill();
  }

  ctx.strokeStyle = 'rgba(255,190,120,.8)';
  ctx.lineWidth = 1.2;
  for (let i = 0; i < 9; i++) {
    const x = size / 2 + (random() - 0.5) * size * 0.46;
    const y = size / 2 + (random() - 0.5) * size * 0.4;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.quadraticCurveTo(x + 3, y - 4, x + 6, y - 7);
    ctx.stroke();
  }

  ctx.fillStyle = 'rgba(255,255,255,.55)';
  for (let i = 0; i < 26; i++) {
    const angle = random() * Math.PI * 2;
    const distance = random() * size * 0.3;
    ctx.beginPath();
    ctx.arc(size / 2 + Math.cos(angle) * distance, size / 2 + Math.sin(angle) * distance * 0.9, 0.7, 0, Math.PI * 2);
    ctx.fill();
  }
}

