import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
page.on('console', m => console.log('console:', m.type(), m.text()))
page.on('pageerror', e => console.log('error:', e.message))
await page.goto('http://localhost:3000', { waitUntil: 'load' })
await page.click('#start-btn')
await page.waitForTimeout(1600)
const data = await page.evaluate(() => ({
  markers: [...document.querySelectorAll('.marker')].map(el => ({ transform: el.style.transform, label: el.getAttribute('aria-label'), opacity: el.style.opacity })),
  pods: window.__weedfirm.scene.podVisuals.map(v => ({ x: v.group.position.x, z: v.group.position.z, strain: v.strainId, plant: !!v.plantRoot })),
  state: window.__weedfirm.state.pods.map(p => ({ p: p.plant?.progress, s: p.plant?.strainId })),
  camera: { pos: window.__weedfirm.scene.camera.position.toArray(), target: window.__weedfirm.scene.baseTarget?.toArray(), mobile: window.__weedfirm.scene.mobile, w: window.__weedfirm.scene.width, h: window.__weedfirm.scene.height }
}))
console.log(JSON.stringify(data, null, 2))
await page.screenshot({ path: 'screenshots/debug.png' })
await browser.close()
EOF
