  const halfWidth = 0.16;
  const segments = 84;
  const points = [];
  for (let i = 0; i <= segments; i++) {
    const angle = -spread + (i / segments) * spread * 2;
    let radius = 0.035;
    for (let k = 0; k < centers.length; k++) {
      const d = Math.abs(angle - centers[k]);
      if (d < halfWidth) {
        const t = d / halfWidth;
        const profile = Math.pow(1 - t * t, 0.55);
        radius = Math.max(radius, lengths[k] * profile);
