const leafCache = new Map();
const budCache = new Map();

/** Palmate cannabis leaf: seven narrow serrated leaflets in one silhouette. */
function leafGeometry(length) {
  const key = length.toFixed(3);
  if (leafCache.has(key)) return leafCache.get(key);

  const shape = new THREE.Shape();
  const spread = 1.0;
  const centers = [-0.92, -0.62, -0.31, 0, 0.31, 0.62, 0.92];
  const lengths = [0.5, 0.75, 0.92, 1, 0.92, 0.75, 0.5];
  const halfWidth = 0.155;
  const segments = 96;

  shape.moveTo(0, 0);
  for (let i = 0; i <= segments; i++) {
    const angle = -spread + (i / segments) * spread * 2;
    let radius = 0.03;
    for (let k = 0; k < centers.length; k++) {
      const distance = Math.abs(angle - centers[k]);
      if (distance < halfWidth) {
        const t = distance / halfWidth;
        radius = Math.max(radius, lengths[k] * Math.pow(1 - t * t, 0.55));
      }
    }
    const serration = i % 2 === 0 ? 1 : 0.972;
    const scale = length * radius * serration;
    shape.lineTo(Math.sin(angle) * scale, Math.cos(angle) * scale * 1.06);
  }
  shape.closePath();

  const geometry = new THREE.ShapeGeometry(shape);
  geometry.computeVertexNormals();
  leafCache.set(key, geometry);
  return geometry;
}

function budGeometry(radius) {
  const key = radius.toFixed(3);
  if (budCache.has(key)) return budCache.get(key);
  const geometry = new THREE.IcosahedronGeometry(radius, 1);
  budCache.set(key, geometry);
  return geometry;
}

