        this.scene.burst(index, strainById(result.strainId).bud);
        this.toast(`Geerntet ${formatGrams(result.grams)}`, `${result.strainName} · Note ${result.grade} · Wert ${formatMoney(result.value)}`, 'success', 'bud');
